// core-sync: 1.0.0 — deterministic exact-match search order (no substring matching):
// 1 Lead.MobilePhone, 2 Lead.Phone, 3 Contact.MobilePhone, 4 Contact.Phone,
// 5 Person Account phone (when enabled), 6 configured custom phone fields.
// Field map is provided via SF_FIELD_MAP_JSON (resolved local copy of config/salesforce-field-map.json).
const map = JSON.parse($env.SF_FIELD_MAP_JSON || '{}');
const m = map.mappings || {};
const f = (k, fb) => (m[k] && m[k].field !== 'UNMAPPED' ? m[k].field : fb);
const phone = $json.customer_number;
if (!/^\+\d{8,15}$/.test(phone || '')) throw new Error('SB-03: customer_number is not E.164');
const esc = phone.replace(/'/g, '');
// Salesforce stores phones inconsistently; we match on exact E.164 plus the common US 10-digit form — still exact-value equality, never LIKE.
const bare = esc.replace(/^\+1/, '');
const tenDigit = bare.length === 10 ? `${bare.slice(0,3)}-${bare.slice(3,6)}-${bare.slice(6)}` : null;
const variants = [esc, bare, tenDigit, tenDigit ? `(${bare.slice(0,3)}) ${bare.slice(3,6)}-${bare.slice(6)}` : null].filter(Boolean);
const inList = variants.map(v => `'${v}'`).join(',');
const optFields = ['ai_enabled','human_takeover','sms_consent','sms_opt_out','wrong_number','conversation_stage','application_link','followup_date','followup_attempt','appointment_status','last_inbound_date','business_state','industry','time_in_business','monthly_gross_revenue','requested_amount','use_of_funds']
  .map(k => m[k]).filter(s => s && s.object === 'Lead' && s.field !== 'UNMAPPED').map(s => s.field);
const leadFields = ['Id','IsConverted','ConvertedContactId','ConvertedAccountId','ConvertedOpportunityId','FirstName','LastName','Company','OwnerId','Status', f('email','Email'), ...optFields].filter((v,i,a) => a.indexOf(v) === i);
const soqlLead = `SELECT ${leadFields.join(', ')} FROM Lead WHERE ${f('mobile_phone','MobilePhone')} IN (${inList}) OR ${f('phone','Phone')} IN (${inList})`;
const soqlContact = `SELECT Id, FirstName, LastName, AccountId, OwnerId, MailingPostalCode FROM Contact WHERE MobilePhone IN (${inList}) OR Phone IN (${inList})`;
return [{ json: { ...$json, soqlLead, soqlContact, field_map_present: !!map.mappings, phone_variants: variants } }];

// core-sync: 1.0.0 — mirrors resolveRecord in scripts/lib/agent-core.mjs.
const src = $('Build Deterministic SOQL').first().json;
const map = JSON.parse($env.SF_FIELD_MAP_JSON || '{}');
const m = map.mappings || {};
const fname = (k) => (m[k] && m[k].field !== 'UNMAPPED') ? m[k].field : null;
let leadRes = {}, contactRes = {};
try { leadRes = $('Salesforce: Query Leads').first().json; } catch (e) { leadRes = { __failed: true }; }
try { contactRes = $('Salesforce: Query Contacts').first().json; } catch (e) { contactRes = { __failed: true }; }
if (leadRes.__failed || contactRes.__failed) {
  return [{ json: { correlation_id: src.correlation_id, outcome: 'resolver_error', detail: 'salesforce query failed', customer_ref: src.customer_ref } }];
}
const leads = (leadRes.records || []).map(r => ({ object: 'Lead', id: r.Id, isConverted: r.IsConverted === true, convertedContactId: r.ConvertedContactId || null, convertedOpportunityId: r.ConvertedOpportunityId || null, raw: r }));
const contacts = (contactRes.records || []).map(r => ({ object: 'Contact', id: r.Id, raw: r }));
// Deterministic priority: Lead matches take precedence over Contact matches;
// a converted Lead resolves to its Contact. Priority only breaks ties BETWEEN
// objects — multiple records within the winning object level is still ambiguous.
const pool = leads.length ? leads : contacts;
const mapped = pool.map(c => c.object === 'Lead' && c.isConverted && c.convertedContactId ? { ...c, resolvedObject: 'Contact', resolvedId: c.convertedContactId, viaConvertedLead: true } : { ...c, resolvedObject: c.object, resolvedId: c.id });
const uniq = [...new Set(mapped.map(c => `${c.resolvedObject}:${c.resolvedId}`))];
let outcome, record = null;
if (uniq.length === 0) outcome = 'no_match';
else if (uniq.length > 1) outcome = 'multiple_match';
else {
  record = mapped[0];
  const raw = record.raw || {};
  const flag = (k) => { const fn = fname(k); return fn && raw[fn] !== undefined ? String(raw[fn]) === 'true' : null; };
  if (flag('sms_opt_out') === true) outcome = 'opted_out';
  else if (flag('wrong_number') === true) outcome = 'wrong_number';
  else if (flag('human_takeover') === true) outcome = 'human_takeover';
  else if (flag('ai_enabled') === false) outcome = 'ai_disabled';
  else outcome = 'single_match';
}
// Sanitized context: ONLY approved fields; never raw record, never OwnerId exposed to the model.
let sanitized = null;
if (record) {
  const raw = record.raw || {};
  const val = (k, fb) => { const fn = fname(k) || fb; return fn ? raw[fn] ?? null : null; };
  sanitized = {
    object: record.resolvedObject,
    record_ref: `${record.resolvedObject}:${record.resolvedId}`,
    first_name: raw.FirstName ?? null,
    business_name: raw.Company ?? null,
    zip_code: raw.MailingPostalCode ?? null,
    lead_status: raw.Status ?? null,
    conversation_stage: val('conversation_stage'),
    ai_enabled: fname('ai_enabled') ? String(raw[fname('ai_enabled')]) === 'true' : true,
    human_takeover: fname('human_takeover') ? String(raw[fname('human_takeover')]) === 'true' : false,
    sms_consent: fname('sms_consent') ? String(raw[fname('sms_consent')]) === 'true' : null,
    sms_opt_out: fname('sms_opt_out') ? String(raw[fname('sms_opt_out')]) === 'true' : false,
    wrong_number: fname('wrong_number') ? String(raw[fname('wrong_number')]) === 'true' : false,
    application_link_on_file: !!val('application_link'),
    known_fields: { first_name: raw.FirstName ?? null, last_name: raw.LastName ?? null, business_name: raw.Company ?? null, email: raw.Email ?? null, business_state: val('business_state'), industry: val('industry'), time_in_business_months: val('time_in_business'), monthly_gross_revenue: val('monthly_gross_revenue'), requested_amount: val('requested_amount'), use_of_funds: val('use_of_funds') },
    via_converted_lead: record.viaConvertedLead === true,
    converted_opportunity_id: record.convertedOpportunityId || null
  };
}
return [{ json: { correlation_id: src.correlation_id, customer_ref: src.customer_ref, customer_number: src.customer_number, outcome, candidate_count: uniq.length, sanitized, record_id: record ? record.resolvedId : null, record_object: record ? record.resolvedObject : null, field_map_present: src.field_map_present } }];

// core-sync: 1.0.0 — mirrors selectApplication/verificationLevel in scripts/lib/agent-core.mjs.
const res = $('Resolve Record (Never Guess)').first().json;
let opps = [];
try { const q = $('Salesforce: Query Open Opportunities').first().json; opps = (q.records || []).map(r => ({ id: r.Id, stage: r.StageName, closed: r.IsClosed === true, explicitly_linked: res.sanitized && res.sanitized.converted_opportunity_id === r.Id })); } catch (e) { opps = res.sanitized && res.sanitized.converted_opportunity_id ? [{ id: res.sanitized.converted_opportunity_id, stage: null, closed: false, explicitly_linked: true }] : []; }
function selectApplication(apps) {
  const list = apps.filter(a => !a.closed);
  const linked = list.filter(a => a.explicitly_linked);
  if (linked.length === 1) return { outcome: 'selected', application: linked[0] };
  if (linked.length > 1) return { outcome: 'ambiguous', candidates: linked.map(a => a.id) };
  if (list.length === 1) return { outcome: 'selected', application: list[0] };
  if (list.length === 0) return { outcome: 'none' };
  return { outcome: 'ambiguous', candidates: list.map(a => a.id) };
}
const appSel = selectApplication(opps);
// Verification: level 0 by default. Level 1 requires exactly one match + a
// confirmed non-sensitive factor — the CONFIRMATION happens conversationally in
// SB-04/SB-05; here we expose which factors are available to confirm against.
const verification = {
  current_level: 0,
  level1_available: res.outcome === 'single_match',
  confirmation_factors_available: res.sanitized ? ['first_name', 'business_name', 'zip_code'].filter(k => !!res.sanitized[k]) : [],
  level2_provider_configured: !!($env.VERIFICATION_LEVEL2_PROVIDER_URL)
};
const out = { ...res, application_selection: appSel, verification };
console.log(JSON.stringify({ level: 'info', workflow: 'SB-03', workflow_version: '1.0.0', correlation_id: res.correlation_id, action: 'resolve', outcome: res.outcome, application_outcome: appSel.outcome, record_ref: res.sanitized ? res.sanitized.record_ref : null, ts: new Date().toISOString() }));
return [{ json: out }];
